mapper.select:
select rc.rental_contract_no, rc.cust_id, rc.ent_ceo_no, ec.ent_nm , rc.sell_products_no, p.products_nm , rc.rental_contract_status, rc.contract_quantity, rc.contract_period, rc.rental_start_date, rc.rental_end_date, rc.rental_cancel_date, rc.contract_date from rental_contract rc LEFT JOIN ent_ceo ec ON rc.ent_ceo_no = ec.ent_ceo_no INNER JOIN sell_products sp ON rc.sell_products_no = sp.sell_products_no INNER JOIN products p ON sp.products_no = p.products_no WHERE rc.cust_id=#{custId}
AND rc.rental_contract_status = #{searchKey}
ORDER BY ec.ent_nm, rc.contract_date;
